solvers
{
    h
    {
        solver          PCG;
        preconditioner  DIC;
        tolerance       1e-10;
        relTol          0.01;
    }

    hFinal
    {
        $h;
        tolerance       1e-10;
        relTol          0;
    }

    hU
    {
        solver          smoothSolver;
        smoother        GaussSeidel;
        tolerance       1e-10;
        relTol          0.1;
    }

    hUFinal
    {
        $hU;
        tolerance       1e-10;
        relTol          0;
    }
}

